+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void directoryShowsNamesAndOrderedSpecialtiesWithoutAuthentication() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        assertEquals(6, test(grid).size());
+        assertEquals("James", test(grid).getCellText(0, 0));
+        assertEquals("Carter", test(grid).getCellText(0, 1));
+        assertEquals("none", test(grid).getCellText(0, 2));
+        assertEquals("Linda", test(grid).getCellText(1, 0));
+        assertEquals("dentistry, surgery", test(grid).getCellText(1, 2));
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Veterinarians navigation should remain available");
+        assertEquals("vets", link.getPath());
+        assertEquals(6, dsl.fetchCount(VETS));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryKeepsAnEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+        navigate(VetsView.class);
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void callbackLoadsOnlyRequestedPagesIncludingTheFinalPartialPage() {
+        for (int i = 0; i < 121; i++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Extra", "Vet%03d".formatted(i)).execute();
+        }
+        navigate(VetsView.class);
+        var provider = grid().getDataProvider();
+        assertFalse(provider.isInMemory());
+        assertEquals(127, provider.size(new Query<>()));
+        var first = provider.fetch(new Query<>(0, 50, List.of(), null, null)).toList();
+        var second = provider.fetch(new Query<>(50, 50, List.of(), null, null)).toList();
+        var last = provider.fetch(new Query<>(100, 50, List.of(), null, null)).toList();
+        assertEquals(50, first.size());
+        assertEquals(50, second.size());
+        assertEquals(27, last.size());
+        assertEquals(127, java.util.stream.Stream.of(first, second, last)
+                .flatMap(List::stream).map(Vet::id).distinct().count());
+        assertTrue(provider.fetch(new Query<>(127, 50, List.of(), null, null)).findAny().isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void failedPageFetchShowsApplicationErrorAndRemovesGrid() {
+        navigate(VetsView.class);
