+        // Transactional DDL is rolled back after the test, restoring the real database.
+        dsl.alterTable(SPECIALTIES).renameTo("unavailable_specialties").execute();
+        assertEquals(0, provider.fetch(new Query<>(0, 50, List.of(), null, null)).count());
